 35→func (d *Droid) IsTransientError(out Output, err error) bool {
 36→	if err == nil {
 37→		return false
 38→	}
 39→	combined := out.Stdout + out.Stderr
 40→	transientPatterns := []string{
 41→		"overloaded",
 42→		"rate limit",
 43→		"529",
 44→		"503",
 45→		"ECONNRESET",
 46→		"ETIMEDOUT",
 47→	}
 48→	for _, p := range transientPatterns {
 49→		if strings.Contains(combined, p) {
 50→			return true
 51→		}
 52→	}
 53→	return false
 54→}
