 79→func (d *Droid) Bootstrap() error {
 80→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
 81→	if apiKey == "" {
 82→		return nil
 83→	}
 84→
 85→	home, err := os.UserHomeDir()
 86→	if err != nil {
 87→		return fmt.Errorf("get home dir: %w", err)
 88→	}
 89→	dir := filepath.Join(home, ".factory")
 90→	if err := os.MkdirAll(dir, 0o755); err != nil {
 91→		return fmt.Errorf("mkdir %s: %w", dir, err)
 92→	}
 93→
 94→	settingsPath := filepath.Join(dir, "settings.json")
 95→
 96→	// Read existing settings to merge (hooks may already be configured
 97→	// in the repo-local .factory/settings.json, but the global config
 98→	// at ~/.factory/settings.json might have other pre-existing entries).
 99→	var settings droidSettings
100→	if data, readErr := os.ReadFile(settingsPath); readErr == nil {
101→		// Best-effort merge: ignore parse errors and start fresh
102→		_ = json.Unmarshal(data, &settings)
103→	}
104→
105→	// Replace or add the BYOK model entry.
106→	byokModel := droidCustomModel{
107→		DisplayName:    droidCustomModelDisplayName,
108→		Model:          droidCustomModelBaseID,
109→		BaseURL:        "https://api.anthropic.com",
110→		APIKey:         apiKey,
111→		Provider:       "anthropic",
112→		MaxOutputToken: 8192,
113→	}
114→
115→	found := false
116→	for i, m := range settings.CustomModels {
117→		if m.Model == byokModel.Model {
118→			settings.CustomModels[i] = byokModel
119→			found = true
120→			break
121→		}
122→	}
123→	if !found {
124→		settings.CustomModels = append(settings.CustomModels, byokModel)
125→	}
126→
127→	data, err := json.MarshalIndent(settings, "", "  ")
128→	if err != nil {
129→		return fmt.Errorf("marshal settings: %w", err)
130→	}
131→	return os.WriteFile(settingsPath, data, 0o644)
132→}
