181→func (d *Droid) StartSession(ctx context.Context, dir string) (Session, error) {
182→	name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
183→	// Unset CI and GITHUB_ACTIONS so Droid doesn't enter single-turn/headless
184→	// mode — it checks these vars and skips interactive input after the first turn.
185→	s, err := NewTmuxSession(name, dir, []string{"CI", "GITHUB_ACTIONS", "ENTIRE_TEST_TTY"}, d.Binary(), "--model", defaultDroidModel, "--skip-permissions-unsafe")
186→	if err != nil {
187→		return nil, err
188→	}
189→
190→	// Wait for the interactive prompt indicator.
191→	if _, err := s.WaitFor(`>`, 30*time.Second); err != nil {
192→		_ = s.Close()
193→		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
194→	}
195→
196→	// Droid auto-generates a greeting on startup which fires a Stop hook.
197→	// Wait for the greeting turn to fully complete before accepting prompts.
198→	time.Sleep(2 * time.Second)
199→	s.stableAtSend = ""
200→
201→	return s, nil
202→}
