192→func ensureGitInfoExcludeContains(repoDir, entry string) error {
193→	excludePath := filepath.Join(repoDir, ".git", "info", "exclude")
194→
195→	data, err := os.ReadFile(excludePath)
196→	if err != nil && !errors.Is(err, os.ErrNotExist) {
197→		return fmt.Errorf("read %s: %w", excludePath, err)
198→	}
199→
200→	normalized := strings.ReplaceAll(string(data), "\r\n", "\n")
201→	for _, line := range strings.Split(normalized, "\n") {
202→		if strings.TrimSpace(line) == entry {
203→			return nil
204→		}
205→	}
206→
207→	var b strings.Builder
208→	if len(data) > 0 {
209→		b.Write(data)
210→		if data[len(data)-1] != '\n' {
211→			b.WriteByte('\n')
212→		}
213→	}
214→	b.WriteString(entry)
215→	b.WriteByte('\n')
216→
217→	if err := os.MkdirAll(filepath.Dir(excludePath), 0o755); err != nil {
218→		return fmt.Errorf("create %s: %w", filepath.Dir(excludePath), err)
219→	}
220→	if err := os.WriteFile(excludePath, []byte(b.String()), 0o644); err != nil {
221→		return fmt.Errorf("write %s: %w", excludePath, err)
222→	}
223→	return nil
224→}
