288→// runScenario runs the test function and recovers from errScenarioRestart
289→// panics triggered by transient API errors in RunPrompt. Returns true if
290→// the scenario should be restarted with a fresh repository.
291→func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
292→	t.Helper()
293→	defer func() {
294→		if r := recover(); r != nil {
295→			if _, ok := r.(errScenarioRestart); ok {
296→				restarted = true
297→				return
298→			}
299→			panic(r) // re-panic for unexpected panics
300→		}
301→	}()
302→	fn(t, s, ctx)
303→	return false
304→}
305→
306→const maxScenarioRestarts = 2 // restart up to 2 times = 3 total attempts
307→
308→// errScenarioRestart is panicked by RunPrompt when a transient API error is
309→// detected. ForEachAgent recovers from this panic and restarts the test
310→// scenario with a fresh repository, avoiding stale CLI state from the failed
311→// attempt.
312→type errScenarioRestart struct {
313→	msg string
314→}
315→
316→// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
317→// and returns the result. If the agent reports a transient API error, it
318→// panics with errScenarioRestart to trigger a full scenario restart in
319→// ForEachAgent (see runScenario).
320→func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
321→	t.Helper()
322→	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
323→	s.logPromptResult(out)
324→
325→	if err != nil && s.Agent.IsTransientError(out, err) {
326→		errMsg := fmt.Sprintf("transient API error (stderr: %s)", strings.TrimSpace(out.Stderr))
327→		t.Logf("%s — restarting scenario", errMsg)
328→		fmt.Fprintf(s.ConsoleLog, "> [transient] %s — restarting scenario\n", errMsg)
329→		panic(errScenarioRestart{msg: errMsg})
330→	}
331→
332→	return out, err
333→}
